public class ProblemB {

    private void execute(char[] data, PrintWriter outStream) {
        int index = 0;
        int maxLen = 0;
        int pairsCount = 0;
        boolean inParen = false;
        while (index < data.length) {
            if (data[index] == '(') {
                inParen = true;
            } else if (data[index] == ')') {
                inParen = false;
            } else if (Character.isLetter(data[index]))
                index--;
            if (inParen) {
                while (++index != data.length && data[index] != ')' && !Character.isLetter(data[index]));
                if (index == data.length || !Character.isLetter(data[index])) {
                    continue;
                }
                while (Character.isLetter(data[++index]));
                pairsCount++;
            } else {
                while (++index != data.length && data[index] != '(' && !Character.isLetter(data[index]));
                if (index == data.length || !Character.isLetter(data[index])) {
                    continue;
                }
                int start = index;
                while (++index != data.length && Character.isLetter(data[index]));
                maxLen = Math.max(maxLen, index - start);
            }
        }
        outStream.println(maxLen + " " + pairsCount);
    }

    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            br.readLine();
            new ProblemB().execute(br.readLine().toCharArray(), pw);
